import { useEffect, useState } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import { useInView } from '@/hooks/useInView';

const WORDS = ['灵感', '动效'];
/** one full morph cycle */
const CYCLE_MS = 1800;

/**
 * Effect — two bold 64px words morph into each other through a blur(12px→0)
 * + opacity + scale cross-dissolve; words are absolutely centered so the
 * width difference between them never causes layout shift.
 */
export default function MorphingTextPreview() {
  const { ref, inView } = useInView<HTMLDivElement>();
  const [index, setIndex] = useState(0);

  useEffect(() => {
    if (!inView) return;
    const timer = window.setInterval(() => setIndex((i) => (i + 1) % WORDS.length), CYCLE_MS);
    return () => window.clearInterval(timer);
  }, [inView]);

  return (
    <div ref={ref} className="flex h-full w-full items-center justify-center px-6">
      <span
        className="relative flex h-[104px] w-[260px] items-center justify-center"
        aria-label={WORDS[index]}
      >
        <AnimatePresence initial={false}>
          <motion.span
            key={index}
            className="absolute inline-block whitespace-nowrap text-[64px] font-bold leading-none tracking-[-0.02em] text-zinc-950 will-change-transform"
            initial={{ opacity: 0, scale: 1.18, filter: 'blur(12px)' }}
            animate={{ opacity: 1, scale: 1, filter: 'blur(0px)' }}
            exit={{ opacity: 0, scale: 0.85, filter: 'blur(12px)' }}
            transition={{ duration: 1.1, ease: [0.16, 1, 0.3, 1] as [number, number, number, number] }}
          >
            {WORDS[index]}
          </motion.span>
        </AnimatePresence>
      </span>
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';

/**
 * IntersectionObserver hook with enter/exit hysteresis, used to gate live previews.
 *
 * Why hysteresis: a single observer with a small rootMargin causes boundary thrash —
 * cards just inside the margin mount, then unmount the moment they scroll a few px
 * past the viewport edge, producing visible white flashes ("闪屏") while scrolling.
 *
 * - enter observer: mounts the preview 240px BEFORE it reaches the viewport,
 *   so content is already there when the user sees it.
 * - exit observer: keeps the preview mounted until it is 600px PAST the viewport,
 *   so briefly scrolling by never blanks a card.
 */
export function useInView<T extends HTMLElement>(enterMargin = '240px', exitMargin = '600px') {
  const ref = useRef<T | null>(null);
  const [inView, setInView] = useState(() => typeof IntersectionObserver === 'undefined');

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (typeof IntersectionObserver === 'undefined') return;

    const enter = new IntersectionObserver(
      (entries) => {
        if (entries[0]?.isIntersecting) setInView(true);
      },
      { rootMargin: enterMargin, threshold: 0 },
    );
    const exit = new IntersectionObserver(
      (entries) => {
        if (entries[0] && !entries[0].isIntersecting) setInView(false);
      },
      { rootMargin: exitMargin, threshold: 0 },
    );

    enter.observe(el);
    exit.observe(el);
    return () => {
      enter.disconnect();
      exit.disconnect();
    };
  }, [enterMargin, exitMargin]);

  return { ref, inView };
}

