@layer base {
  * {
    @apply border-border;
  }
  html {
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
  }
  body {
    @apply bg-white text-zinc-950 font-sans;
    font-feature-settings: 'cv02', 'cv03', 'cv04';
  }
  ::selection {
    background: #09090b;
    color: #ffffff;
  }
  :focus-visible {
    outline: 2px solid #09090b;
    outline-offset: 2px;
  }
}
